from pathlib import Path

def contar_linhas_em_loop(caminho):
    arquivo = Path(caminho)
    if not arquivo.exists():
        return 0

    total = 0
    with arquivo.open('r', encoding='utf-8') as handle:
        for linha in handle:
            if linha.strip():
                total += 1
    return total

